import ActivityKit
import SwiftUI

/// The app icons a user can pick in Settings › Theme.
///
/// Each case's `alternateName` is the key under `CFBundleAlternateIcons` in
/// project.yml, except `.classic`, which is the primary icon baked into the asset
/// catalog — `setAlternateIconName(nil)` is how you go back to it.
///
/// The artwork is generated by `brand/make-alt-icons.py` from the 1024 masters in
/// `brand/alt-icons/`, as loose `AppIcon-<name>@2x/@3x.png` at the bundle root.
/// Adding one means: drop in a master, re-run that script, add a case here, list it
/// under `CFBundleAlternateIcons` in project.yml, then `xcodegen generate`.
enum AppIconOption: String, CaseIterable, Identifiable {
    /// Widget extensions cannot inspect `UIApplication.alternateIconName`, so the
    /// effective selection also lives in the shared App Group for Live Activities.
    static let sharedDefaults = UserDefaults(suiteName: "group.com.inbox2.ios")
    static let sharedDefaultsKey = "inbox2_active_app_icon"

    case classic
    case sun
    case vennlight
    case graffiti
    case groovebox

    var id: String { rawValue }

    /// What `UIApplication.alternateIconName` uses. nil == the primary icon.
    var alternateName: String? { self == .classic ? nil : rawValue }

    /// Loose bundle PNG backing the picker thumbnail — including for the primary,
    /// which ships a loose copy precisely so the row has something to draw.
    var previewImageName: String { "AppIcon-\(rawValue)" }

    var label: String {
        switch self {
        case .classic: "Classic"
        case .sun: "Rising sun"
        case .vennlight: "Venn"
        case .graffiti: "Graffiti"
        case .groovebox: "Groovebox"
        }
    }

    var blurb: String {
        switch self {
        case .classic: "The original gradient-ring 2"
        case .sun: "Red rays, cream ground"
        case .vennlight: "Three discs on white, no numeral"
        case .graffiti: "Wildstyle X"
        case .groovebox: "Line-art cube on the grid"
        }
    }

    /// What the home screen is showing right now.
    @MainActor static var current: AppIconOption {
        let name = UIApplication.shared.alternateIconName
        return allCases.first { $0.alternateName == name } ?? .classic
    }

    /// Returns the icon actually in effect afterwards — iOS silently refuses on
    /// some device states, so callers should trust this over the requested value.
    @MainActor static func apply(_ option: AppIconOption) async -> AppIconOption {
        guard UIApplication.shared.supportsAlternateIcons else { return current }
        guard option.alternateName != UIApplication.shared.alternateIconName else {
            persistCurrent()
            return option
        }
        do {
            try await UIApplication.shared.setAlternateIconName(option.alternateName)
        } catch {
            Log.ui.error("app icon change to \(option.rawValue) failed: \(error.localizedDescription)")
        }
        persistCurrent()
        await refreshLiveActivities()
        return current
    }

    /// Call on launch too, so people who picked an alternate icon before this
    /// version get the correct mark on an already-running Live Activity.
    @MainActor static func syncSharedSelection() {
        persistCurrent()
    }

    @MainActor private static func persistCurrent() {
        sharedDefaults?.set(current.rawValue, forKey: sharedDefaultsKey)
    }

    /// A Live Activity is a rendered snapshot. Re-publish its unchanged content
    /// after the selection changes so the lock screen and Dynamic Island redraw now.
    @MainActor private static func refreshLiveActivities() async {
        for activity in Activity<MailActivityAttributes>.activities {
            await activity.update(ActivityContent(state: activity.content.state,
                                                  staleDate: activity.content.staleDate))
        }
        for activity in Activity<ZoneActivityAttributes>.activities {
            await activity.update(ActivityContent(state: activity.content.state,
                                                  staleDate: activity.content.staleDate))
        }
    }
}
